import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.CWYzGJW1.js";const p=JSON.parse('{"title":"開源模型選型與資安適用評分","description":"Hugging Face 上約 318 萬個模型中, 只要 6,328 個就涵蓋近六個月 95% 的下載量.","frontmatter":{"description":"Hugging Face 上約 318 萬個模型中, 只要 6,328 個就涵蓋近六個月 95% 的下載量."},"headers":[],"relativePath":"decide/model-selection.md","filePath":"decide/model-selection.md","lastUpdated":1793060541000}'),o={name:"decide/model-selection.md"};function i(l,t,n,h,c,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="開源模型選型與資安適用評分" tabindex="-1">開源模型選型與資安適用評分 <a class="header-anchor" href="#開源模型選型與資安適用評分" aria-label="Permalink to &quot;開源模型選型與資安適用評分&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 下載數含 CI 與自動化流程的重複拉取, 只能當相對熱度; 任務類型與授權由模型作者自行標示, 可能漏填或誤填; 評分權重與等級門檻為整理者推論, 分數不代表偵測效果; 「多數下載來自程式」為推論 (信心: 中); 文中的類比為整理者所寫, 不代表技術上完全等同; 見頁尾「參考來源」</li></ul></div><p><strong>結論</strong>: Hugging Face 上約 318 萬個模型中, 只要 6,328 個就涵蓋近六個月 95% 的下載量. 依意思找資料的檢索模型, 下載量與聊天等生成式模型相當, 下載第一名的單一模型也是檢索用的嵌入模型; 走紅的模型多半同時具備「小, 授權寬鬆, 被框架設為預設值, 有生態系轉發」四項條件 (信心: 中, 屬推論). 依本頁的評分方法, 符合來源白名單的熱門模型中有 54 個值得優先評估用在資安工作, 以 AI 應用防護, 個資偵測與資安專用的檢索模型為主.</p><p><strong>下載試算表</strong>: <a href="../files/model-security-scoring.xlsx" target="_self" download="">model-security-scoring.xlsx</a> (Excel 格式, 約 2,500 個模型的評分明細). 權重與等級門檻可直接修改, 分數與排名會自動重算.</p><table tabindex="0"><thead><tr><th>分頁</th><th>內容</th></tr></thead><tbody><tr><td>摘要</td><td>篩選漏斗, 適用等級分布, 依用途彙總, 總排名前 20</td></tr><tr><td>評分方法</td><td>八個評分面向與權重 (可修改), 等級門檻, 排除條件, 任務類型對照, 來源分級名單</td></tr><tr><td>資安適用排名</td><td>通過篩選的模型, 含各面向得分, 授權, 參數量, 權重格式與模型頁面連結</td></tr><tr><td>依用途前十</td><td>18 個資安用途類別各自的前十名</td></tr><tr><td>排除清單</td><td>未通過排除條件的模型與原因</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>Hugging Face</td><td>最大的開源模型分享網站, 多數開源模型都從這裡下載</td></tr><tr><td>嵌入模型 (embedding model)</td><td>把文字換成一串數字 (向量), 讓電腦能依「意思」比較兩段文字像不像</td></tr><tr><td>重排序模型 (reranker)</td><td>把搜尋找到的段落重新排名, 把最相關的放到最前面</td></tr><tr><td>量化版本 (quantized)</td><td>把模型存得粗一點, 檔案變小, 一般電腦也跑得動</td></tr><tr><td>授權 (license)</td><td>模型作者規定的使用條件, 例如能不能拿來做商業服務</td></tr></tbody></table></div><h2 id="下載量集中在極少數模型" tabindex="-1">下載量集中在極少數模型 <a class="header-anchor" href="#下載量集中在極少數模型" aria-label="Permalink to &quot;下載量集中在極少數模型&quot;">​</a></h2><p>模型網站上有三百多萬個模型, 但真正常被下載的只有幾千個, 就像書店裡大多數人只買暢銷榜上的書. 挑模型時, 先從這幾千個熱門模型裡找, 文件, 範例與討論都比較多, 遇到問題也比較容易查到解法 (推論, 信心: 中).</p><p>以兩份全站快照 (2026-04-25 與 2026-10-25) 的累計下載數相減, 推算每個模型近六個月的下載量, 再由高到低累加, 結果如下.</p><table tabindex="0"><thead><tr><th>涵蓋近六個月下載量</th><th>所需模型數</th></tr></thead><tbody><tr><td>80%</td><td>1,081 個</td></tr><tr><td>90%</td><td>2,930 個</td></tr><tr><td>95%</td><td>6,328 個</td></tr><tr><td>99%</td><td>84,171 個</td></tr></tbody></table><p>全站去重後共 3,185,807 個模型, 近六個月下載總數約 183.4 億次; 期間內有任何下載的只有 1,809,978 個, 其餘約 43% 完全沒有下載. 從 95% 到 99% 要多看十幾倍的模型, 所以本頁以 95% 為觀察範圍.</p><h2 id="看不見的檢索模型-下載量和聊天模型相當" tabindex="-1">看不見的檢索模型, 下載量和聊天模型相當 <a class="header-anchor" href="#看不見的檢索模型-下載量和聊天模型相當" aria-label="Permalink to &quot;看不見的檢索模型, 下載量和聊天模型相當&quot;">​</a></h2><p>一般人以為最熱門的是聊天機器人, 但幫系統「依意思找資料」的檢索模型, 下載量和生成式模型相當, 下載最多次的單一模型也是檢索模型. 這類模型不直接和人對話, 而是藏在搜尋, 推薦與企業知識庫背後. 它們只負責判斷兩段文字像不像, 不負責寫答案, 所以可以做得很小, 一般 CPU 就跑得動.</p><p>把 6,328 個模型依用途分群後, 下載量分布如下 (分群依模型頁的任務標籤 pipeline_tag 歸類).</p><table tabindex="0"><thead><tr><th>用途分群</th><th>下載占比</th></tr></thead><tbody><tr><td>生成式語言模型與視覺語言模型</td><td>29.5%</td></tr><tr><td>檢索用的嵌入與重排序模型</td><td>27.3%</td></tr><tr><td>傳統自然語言處理 (分類, 實體辨識, 翻譯等)</td><td>12.4%</td></tr><tr><td>作者未標示任務</td><td>10.6%</td></tr><tr><td>語音</td><td>8.3%</td></tr><tr><td>電腦視覺</td><td>6.8%</td></tr><tr><td>時間序列預測</td><td>2.6%</td></tr><tr><td>影像與影音生成</td><td>1.8%</td></tr><tr><td>其他</td><td>0.8%</td></tr></tbody></table><p>檢索模型的下載量幾乎和生成式模型一樣多. 第一名是嵌入模型 <code>sentence-transformers/all-MiniLM-L6-v2</code>, 只有 2,271 萬參數, 六個月約 15.4 億次下載.</p><p>嵌入模型把一段文字轉成一串數字 (向量), 意思相近的文字, 向量也會相近. 可以把它想成一張「意思地圖」, 每段文字都有一個座標; 系統比的是座標距離, 所以搜「勒索軟體」, 也找得到只寫「檔案遭加密並要求贖金」的報告. 嵌入模型的選擇見 <a href="/lanai-handbook/build/m4-retrieval">M4.2 節</a>.</p><p>另外兩個現象:</p><ul><li><strong>小模型扛起過半下載量</strong>: 10 億參數以下的模型占 52.1%, 1 億參數以下也有 24.3%.</li><li><strong>老模型仍是主力</strong>: 654 個模型的建立日期同為 2022-03-02, 合計占 33.0% 的下載量. 這批包含 2018 年發表的 BERT 與 2019 年發表的 GPT-2, 所以這個日期應是平台改版時統一寫入的時間 (推論, 信心: 高); 換句話說, 約三分之一的下載量來自 2022 年 3 月以前上架的模型, 到 2026 年 10 月已超過四年半.</li></ul><h2 id="多數模型是直接拿來用-很少再訓練" tabindex="-1">多數模型是直接拿來用, 很少再訓練 <a class="header-anchor" href="#多數模型是直接拿來用-很少再訓練" aria-label="Permalink to &quot;多數模型是直接拿來用, 很少再訓練&quot;">​</a></h2><p>大家下載模型後, 多半是「縮小一點讓它跑得動」, 而不是「再教它新東西」. 最常見的用法, 是把檢索模型和語言模型串成一條流程: 先找出相關資料, 再請語言模型依資料回答.</p><p>依模型頁標示的衍生關係, 量化版本有 1,649 個, 占 23.7% 的下載量; 微調版本占 14.6%, LoRA 等轉接器只占 0.3%, 合併模型只占 0.1%. 實務上的主要需求是「讓既有模型跑得動, 跑得快」, 而不是「讓模型學會新知識」 (推論, 信心: 中). 是否真的需要訓練, 見 <a href="/lanai-handbook/train/t1-decide">T1</a>.</p><p>最常見的組合是檢索增強生成 (RAG): 嵌入模型先把文件轉成向量存進向量資料庫, 使用者提問時找出相近段落, 交給重排序模型重新排序, 最後才由語言模型寫出回答. 每處理一份文件, 每回答一個問題, 嵌入模型都要執行一次, 這是檢索模型下載量大的結構性原因 (推論, 信心: 中). 組裝方式見 <a href="/lanai-handbook/build/m4-retrieval">M4</a>.</p><h2 id="下載量多半來自程式-不全是真人" tabindex="-1">下載量多半來自程式, 不全是真人 <a class="header-anchor" href="#下載量多半來自程式-不全是真人" aria-label="Permalink to &quot;下載量多半來自程式, 不全是真人&quot;">​</a></h2><p>下載次數不等於使用人數. 很多系統每次重新啟動, 都會自動再下載一次模型; 真人才會按讚, 程式不會. 所以「下載很多, 讚很少」的模型, 多半是被程式反覆下載.</p><p>檢索與傳統自然語言處理模型的下載量, 以自動化拉取為主 (推論, 信心: 中). 判斷過程如下.</p><table tabindex="0"><thead><tr><th>假設</th><th>內容</th></tr></thead><tbody><tr><td>假設 A</td><td>下載量反映真人採用, 檢索模型就是最多人選用的模型</td></tr><tr><td>假設 B</td><td>下載量多半來自自動化流程: RAG 服務每次啟動, CI (持續整合, 程式每次修改後自動建置與測試的流程) 每次執行, 容器每次重建, 都會重新拉取模型</td></tr></tbody></table><p>鑑別方式是看讚數. 讚數必須由真人登入點擊; 如果某類模型下載量極高, 讚數卻很少, 代表大部分下載不是真人.</p><table tabindex="0"><thead><tr><th>任務類型</th><th>每百萬次下載得到的讚數</th></tr></thead><tbody><tr><td>重排序 (text-ranking)</td><td>6.1</td></tr><tr><td>句子相似度 (sentence-similarity)</td><td>11.3</td></tr><tr><td>文字生成 (text-generation)</td><td>133.9</td></tr><tr><td>文生圖 (text-to-image)</td><td>765.1</td></tr><tr><td>6,328 個模型平均</td><td>75.5</td></tr></tbody></table><p>差距超過百倍, 支持假設 B. 另有 281 個名稱含 test 或 tiny 的測試用模型入榜, 合計占 1.8% 的下載量. 若日後平台公布排除自動化流量的獨立使用者數, 而檢索模型仍大幅領先, 則改判為假設 A.</p><h2 id="走紅的模型多半同時具備四項條件" tabindex="-1">走紅的模型多半同時具備四項條件 <a class="header-anchor" href="#走紅的模型多半同時具備四項條件" aria-label="Permalink to &quot;走紅的模型多半同時具備四項條件&quot;">​</a></h2><p>一個模型會紅, 通常不是因為它最聰明, 而是因為它最好用: 檔案小, 授權寬鬆, 很多工具預設就用它, 社群也幫忙做出各種版本.</p><table tabindex="0"><thead><tr><th>條件</th><th>證據</th><th>信心</th></tr></thead><tbody><tr><td>被框架設為預設值</td><td>Chroma 是負責存放向量並依相似度查詢的向量資料庫, 官方文件寫明, 預設嵌入模型使用 <code>all-MiniLM-L6-v2</code>, 也就是第一名; 沒有特別指定模型時, 每個新專案都會下載一次</td><td>高</td></tr><tr><td>小到一般 CPU 就能跑</td><td>10 億參數以下的模型占 52.1% 的下載量</td><td>高</td></tr><tr><td>授權寬鬆, 可直接商用</td><td>Apache 2.0 與 MIT 合計占 79.7% 的下載量; 授權檢查方式見<a href="/lanai-handbook/decide/license-flags">授權紅旗</a></td><td>高</td></tr><tr><td>有生態系幫忙轉發</td><td>以 Google 模型為上游的生成式模型共 249 個入榜, 其中 210 個是社群做的量化或微調版本, 讓同一個模型同時出現在多種執行環境</td><td>中</td></tr></tbody></table><p>新模型發布時也會短期爆量: 期間內才上架的 993 個模型占 7.6% 的下載量, 多數是生成式模型, 熱度通常在下一代推出後下降 (推論, 信心: 中).</p><h2 id="資安適用評分-54-個模型值得優先評估" tabindex="-1">資安適用評分: 54 個模型值得優先評估 <a class="header-anchor" href="#資安適用評分-54-個模型值得優先評估" aria-label="Permalink to &quot;資安適用評分: 54 個模型值得優先評估&quot;">​</a></h2><p>為了找出適合用在資安工作的模型, 本頁先刪掉不安全或不能商用的模型, 再依八個面向打分數, 滿分 100. 分數高代表「值得先拿來試」, 不代表「效果一定好」, 實際效果還是要用自己的資料測試.</p><p>評估範圍先依 <a href="/lanai-handbook/build/m3-model-intake">M3</a> 的模型來源白名單原則篩選, 得到 4,242 個熱門模型, 再依序套用六道排除條件, 通過的 2,489 個模型再依八個面向計分.</p><h3 id="六道排除條件" tabindex="-1">六道排除條件 <a class="header-anchor" href="#六道排除條件" aria-label="Permalink to &quot;六道排除條件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>條件</th><th>排除原因</th><th>觸及模型數</th></tr></thead><tbody><tr><td>G1 移除安全護欄或不當用途</td><td>名稱含 uncensored, abliterated 等字樣, 不適合放進防禦流程</td><td>66</td></tr><tr><td>G2 測試用模型</td><td>供框架測試, 非正式用途</td><td>209</td></tr><tr><td>G3 權重格式可執行程式碼</td><td>沒有 safetensors, GGUF 或 ONNX 權重; pickle 格式載入時可能執行任意程式碼 (見 <a href="/lanai-handbook/build/m3-model-intake">M3</a>)</td><td>901</td></tr><tr><td>G4 需執行遠端程式碼</td><td>載入時須開啟 <code>trust_remote_code</code>, 等於執行模型倉庫中的程式</td><td>268</td></tr><tr><td>G5 授權不允許商用</td><td>CC BY-NC 系列與研究專用授權</td><td>190</td></tr><tr><td>G6 無防禦用途</td><td>生成影像, 影音或語音的模型</td><td>354</td></tr></tbody></table><p>一個模型可能同時觸及多項條件, 所以各列加總大於排除總數 (1,753 個).</p><h3 id="八個評分面向" tabindex="-1">八個評分面向 <a class="header-anchor" href="#八個評分面向" aria-label="Permalink to &quot;八個評分面向&quot;">​</a></h3><table tabindex="0"><thead><tr><th>面向</th><th>權重</th><th>計分方式</th></tr></thead><tbody><tr><td>任務適配</td><td>30</td><td>分類, 實體擷取, 檢索與分析類任務最高, 影像與語音類偏低; 專精領域與資安無關者打折</td></tr><tr><td>來源可信度</td><td>15</td><td>原始開發組織最高, 知名社群或重新封裝者次之, 其他帳號最低</td></tr><tr><td>部署可行性</td><td>15</td><td>參數量越小, 越容易在內網部署; 硬體門檻見 <a href="/lanai-handbook/know/k3-hardware">K3</a></td></tr><tr><td>資安專精</td><td>10</td><td>是否以資安資料或資安任務訓練</td></tr><tr><td>授權友善度</td><td>10</td><td>Apache 2.0, MIT 最高; Llama, Gemma 等自訂授權需逐條審查</td></tr><tr><td>採用度</td><td>10</td><td>近六個月下載量的百分位</td></tr><tr><td>維護活躍度</td><td>5</td><td>最後更新時間</td></tr><tr><td>中文支援</td><td>5</td><td>是否標示支援中文或多語</td></tr></tbody></table><p>權重是整理者依一般導入考量設定的推論, 試算表裡可以依自己的情境調整.</p><h3 id="總排名前-15" tabindex="-1">總排名前 15 <a class="header-anchor" href="#總排名前-15" aria-label="Permalink to &quot;總排名前 15&quot;">​</a></h3><table tabindex="0"><thead><tr><th>排名</th><th>模型</th><th>資安用途</th><th>總分</th></tr></thead><tbody><tr><td>1</td><td><code>protectai/deberta-v3-base-prompt-injection-v2</code></td><td>AI 應用防護 (提示注入偵測)</td><td>93.8</td></tr><tr><td>2</td><td><code>gravitee-io/bert-small-pii-detection</code></td><td>個資偵測</td><td>91.3</td></tr><tr><td>3</td><td><code>openai/privacy-filter</code></td><td>個資偵測</td><td>90.5</td></tr><tr><td>4</td><td><code>meta-llama/Prompt-Guard-86M</code></td><td>AI 應用防護</td><td>89.8</td></tr><tr><td>5</td><td><code>fastino/gliner2-privacy-filter-PII-multi</code></td><td>個資偵測</td><td>89.1</td></tr><tr><td>6</td><td><code>cisco-ai/SecureBERT2.0-biencoder</code></td><td>威脅情資檢索</td><td>88.6</td></tr><tr><td>7</td><td><code>protectai/deberta-v3-base-prompt-injection</code></td><td>AI 應用防護</td><td>88.3</td></tr><tr><td>8</td><td><code>cisco-ai/SecureBERT2.0-cross_encoder</code></td><td>威脅情資檢索</td><td>87.3</td></tr><tr><td>9</td><td><code>openai-community/roberta-base-openai-detector</code></td><td>生成內容偵測</td><td>86.4</td></tr><tr><td>10</td><td><code>sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2</code></td><td>檢索與情資關聯</td><td>86.0</td></tr><tr><td>11</td><td><code>intfloat/multilingual-e5-small</code></td><td>檢索與情資關聯</td><td>86.0</td></tr><tr><td>12</td><td><code>intfloat/multilingual-e5-large</code></td><td>檢索與情資關聯</td><td>85.9</td></tr><tr><td>13</td><td><code>intfloat/multilingual-e5-base</code></td><td>檢索與情資關聯</td><td>85.9</td></tr><tr><td>14</td><td><code>meta-llama/Llama-Prompt-Guard-2-86M</code></td><td>AI 應用防護</td><td>84.9</td></tr><tr><td>15</td><td><code>sentence-transformers/paraphrase-multilingual-mpnet-base-v2</code></td><td>檢索與情資關聯</td><td>84.4</td></tr></tbody></table><p>提示注入 (prompt injection) 是指在輸入或外部文件裡夾帶指令, 誘使 AI 偏離原本任務; 「AI 應用防護」類模型負責在內容送進語言模型之前先檢查一次.</p><h3 id="依用途看-資安專用模型很少" tabindex="-1">依用途看, 資安專用模型很少 <a class="header-anchor" href="#依用途看-資安專用模型很少" aria-label="Permalink to &quot;依用途看, 資安專用模型很少&quot;">​</a></h3><table tabindex="0"><thead><tr><th>資安用途類別</th><th>通過篩選的模型數</th><th>最高分</th><th>優先評估數</th></tr></thead><tbody><tr><td>AI 應用防護</td><td>19</td><td>93.8</td><td>9</td></tr><tr><td>個資偵測與去識別化</td><td>15</td><td>91.3</td><td>5</td></tr><tr><td>威脅情資與資安語言</td><td>3</td><td>88.6</td><td>2</td></tr><tr><td>檢索與情資關聯</td><td>269</td><td>86.0</td><td>25</td></tr><tr><td>分析與報告生成 (語言模型)</td><td>972</td><td>82.3</td><td>6</td></tr><tr><td>實體擷取</td><td>357</td><td>82.3</td><td>3</td></tr><tr><td>釣魚與垃圾訊息偵測</td><td>3</td><td>80.7</td><td>1</td></tr><tr><td>日誌異常偵測</td><td>1</td><td>81.7</td><td>1</td></tr><tr><td>時序異常偵測</td><td>53</td><td>77.5</td><td>0</td></tr></tbody></table><p>其餘類別見試算表. 從表格可以看出三件事 (推論, 信心: 中):</p><ol><li><strong>以資安資料訓練的模型很少</strong>: 通過篩選的 2,489 個模型中, 這類模型只有 64 個. 多數資安情境要靠通用模型組成流程, 或自己微調.</li><li><strong>語言模型數量最多, 卻很少達到優先評估</strong>: 972 個語言模型只有 6 個達 80 分, 主要原因是體積大, 部署不易, 授權多為自訂條款. 小型的嵌入與分類模型更適合先導入.</li><li><strong>下載排行找不到所有資安專用模型</strong>: 部分資安專用模型 (例如 Cisco 的 SecureBERT 2.0 實體辨識模型) 下載量低於 95% 門檻, 不在本次評分範圍. 下載排行只能找出「大家都在用」的模型, 資安專用模型要另外主動搜尋.</li></ol><h2 id="怎麼使用這份評分" tabindex="-1">怎麼使用這份評分 <a class="header-anchor" href="#怎麼使用這份評分" aria-label="Permalink to &quot;怎麼使用這份評分&quot;">​</a></h2><p>先找到自己的用途, 挑兩三個高分模型, 照手冊的入庫流程放進來, 再用自己的資料比一比.</p><ol><li>在試算表的「依用途前十」分頁找到自己的情境, 例如要做告警的語意搜尋, 就看「檢索與情資關聯」.</li><li>挑 2 至 3 個候選, 依 <a href="/lanai-handbook/build/m3-model-intake">M3</a> 的流程入庫, 再用自己的資料做 <a href="/lanai-handbook/decide/poc-30days">30 天 PoC</a>.</li><li>用 <a href="/lanai-handbook/build/m6-observability">M6</a> 的評估方式比較候選模型; 分數只代表「值得投入評估的程度」, 實際效果以自己的測試結果為準.</li><li>大型語言模型需要的記憶體與硬體, 見 <a href="/lanai-handbook/know/k2-quantization">K2</a> 與 <a href="/lanai-handbook/know/k3-hardware">K3.4 節</a>.</li></ol><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p><strong>資料來源</strong></p><ul><li>下載量與模型資料: Hugging Face 上公開的全站統計資料集 hub-stats, 取其中記錄每個模型下載數與標籤的 models.parquet, 使用 2026-10-25 版與 2026-04-25 版兩份快照 (2026-10-26 下載). <a href="https://huggingface.co/datasets/cfahlgren1/hub-stats" target="_blank" rel="noreferrer">Hugging Face: cfahlgren1/hub-stats</a></li><li>全站模型數對照: Hugging Face 模型頁 2026-10-26 顯示 3,186,252 個, 與快照去重後的 3,185,807 個相差約 440 個, 差距來自快照時間. <a href="https://huggingface.co/models" target="_blank" rel="noreferrer">Hugging Face: Models</a></li><li>Chroma 預設嵌入模型: 官方文件寫明「Chroma&#39;s default embedding function uses the Sentence Transformers all-MiniLM-L6-v2 model」 (2026-10-26 擷取). <a href="https://docs.trychroma.com/docs/embeddings/embedding-functions" target="_blank" rel="noreferrer">Chroma 文件: Embedding Functions</a></li><li>LangChain 範例模型: LangChain 是串接模型, 檢索與工具的應用程式開發框架; 其官方 Sentence Transformers 整合文件的範例使用 <code>sentence-transformers/all-mpnet-base-v2</code> (2026-10-26 擷取). <a href="https://docs.langchain.com/oss/python/integrations/embeddings/sentence_transformers.md" target="_blank" rel="noreferrer">LangChain 文件: Sentence Transformers</a></li><li>Cisco SecureBERT 2.0: 模型卡說明以資安問答, 治理與指令資料以對比學習訓練, 用途為資安語意搜尋與威脅情資檢索; 實體辨識模型可辨識指標, 惡意程式, 組織, 受影響系統與弱點五類實體. <a href="https://huggingface.co/cisco-ai/SecureBERT2.0-biencoder" target="_blank" rel="noreferrer">Hugging Face: cisco-ai/SecureBERT2.0-biencoder</a>, <a href="https://huggingface.co/cisco-ai/SecureBERT2.0-NER" target="_blank" rel="noreferrer">Hugging Face: cisco-ai/SecureBERT2.0-NER</a></li></ul><p><strong>計算方式與整理者判斷</strong></p><ul><li>近六個月下載量 = 2026-10-25 累計下載數減 2026-04-25 累計下載數; 兩份快照以模型內部 ID 比對, 中途改名的模型不重複計算, 期間新上架者以 0 起算; 累計數不增反減者 (平台修正統計) 以 0 計; 期間內已刪除或轉為私有的模型無法納入.</li><li>用途分群, 讚數比例, 參數量級, 授權占比與衍生關係占比, 皆為整理者依上述資料計算; 任務類型, 授權與衍生關係由模型作者自行標示.</li><li>「2022-03-02 為平台統一寫入的日期」, 「多數下載來自程式」, 「走紅的四項條件」, 「實務需求以部署為主」為整理者推論, 信心標示於正文.</li><li>評分方法 (排除條件, 八個面向, 權重, 等級門檻, 來源分級名單) 為整理者設計, 完整規則見試算表的「評分方法」分頁; 分數不代表偵測效果, 未經實測.</li><li>「暢銷榜」與「意思地圖」為整理者所寫的類比, 無外部來源, 不是技術定義.</li></ul>',58)])])}const u=d(o,[["render",i]]);export{p as __pageData,u as default};
